steps.script:
GameState.state["factions"]["1"].merge({"detachment": "Dread Mob"}, true)
StratagemManager.load_faction_stratagems_for_player(1)
var i := 0
for m in GameState.state.units["U_PROSECUTORS_A"].models:
	m["position"] = {"x": 1080.0 + i * 56.0, "y": 2000.0}
	i += 1
var wall := {"id": "ork11e_test_wall", "type": "ruins", "category": "dense", "height_category": "tall", "height": 5.0, "height_inches": 5.0, "piece_class": "feature", "position": Vector2(560, 850), "size": Vector2(160, 20), "rotation": 0.0, "traits": [], "polygon": PackedVector2Array([Vector2(480, 840), Vector2(640, 840), Vector2(640, 860), Vector2(480, 860)])}
TerrainManager.terrain_features.append(wall)
TerrainManager.terrain_loaded.emit(TerrainManager.terrain_features)
tree.current_scene._recreate_unit_visuals()
return StratagemManager.get_stratagem("faction_ork_dread_mob_stomping_juggernaut").get("implemented", false)

var kw = GameState.get_unit("U_DEFF_DREAD_A").meta.keywords
var m = GameState.get_unit("U_DEFF_DREAD_A").models[0]
var plain = TerrainManager.can_move_through_11e(kw, Vector2(560, 772.76), Vector2(560, 972.76), [], m)
var mobile = TerrainManager.can_move_through_11e(kw, Vector2(560, 772.76), Vector2(560, 972.76), ["MOBILE"], m)
return "%s|%s" % [str(plain.allowed), str(mobile.allowed)]
